import sys

# usage: splitpatch.py patchfile out.patch idx1 idx2 ...   (1-based hunk indices)
patch = open(sys.argv[1]).read()
lines = patch.splitlines(keepends=True)
header, hunks, cur = [], [], None
for ln in lines:
    if ln.startswith('@@'):
        if cur is not None:
            hunks.append(cur)
        cur = [ln]
    elif cur is None:
        header.append(ln)
    else:
        cur.append(ln)
if cur:
    hunks.append(cur)
idxs = [int(x) for x in sys.argv[3:]]
assert all(1 <= i <= len(hunks) for i in idxs), f"bad idx, have {len(hunks)} hunks"
out = header + [l for i in idxs for l in hunks[i - 1]]
open(sys.argv[2], 'w').writelines(out)

